        var tapCalls = 0;
        var receiver = new ValueTask<Result<int>>(Result.Failure<int>(error));
        var outcome = await receiver.TapIf(true, x => { tapCalls++; seen = x; return ValueTask.CompletedTask; });

        Assert.Same(error, outcome.GetError());
        Assert.Equal(0, tapCalls);
    }

